package org.racedaydreams.storage

/** JDK17 original ZIP writer fixtures; ZIP64/duplicate variants use Python ZIP tooling. */
internal object BackupZipFixtures {
    val stored: ByteArray
        get() =
            hex(
                ""
            )

    val deflated: ByteArray
        get() =
            hex(
                ""
            )

    val zip64: ByteArray
        get() =
            hex(
                ""
            )

    val duplicate: ByteArray
        get() =
            hex(
                ""
            )

    private fun hex(text: String): ByteArray =
        ByteArray(text.length / 2) { text.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
}
